window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-e4a0ef5b7f43a824"]={"versions": [{"id": "FIG-e4a0ef5b7f43a824", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / konzeptionelles Entwurfsmodell zur Veranschaulichung des High-Level-Krypto-Designs als Teil des Systementwurfsmodells in AUTOSAR Adaptive Platform (TPS Manifest Specification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Kategorien von Modellelementen und deren Beziehungen dar:</p>\n<ul class=\"fig-list\"><li><strong><code>CryptoKeySlotDesign</code></strong>: Repräsentiert die Design-Ebene eines Key-Slots. Attribute umfassen:\n<ul class=\"fig-list\"><li><code>+ cryptoAgorithmID</code>\n</li><li><code>+ CryptoObjectType</code>\n</li><li><code>+ cryptoKeySlotAllowedUsage</code>\n</li><li><code>+ shared</code> (Werte: <code>true</code> bzw. <code>false</code>)\n</li></ul>\n</li><li><strong><code>CryptoKeySlotUserDesign</code></strong>: Repräsentiert die Design-Ebene eines Verwenders von Key-Slots. Es enthält als Aggregation bzw. Unterelement ein oder mehrere <strong><code>CryptoKeySlotUsageDesign</code></strong>.\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Assoziationen mit Rollenbezeichnungen führen von <code>CryptoKeySlotDesign</code> auf die enthaltenen <code>CryptoKeySlotUsageDesign</code>-Elemente:\n<ul class=\"fig-list\"><li><code>Owner</code>: Weist die Eigentümerschaft des Key-Slots einem Nutzungsdesign innerhalb eines <code>CryptoKeySlotUserDesign</code> zu.\n</li><li><code>User</code>: Weist zusätzliche Nutzungsrechte an einem geteilten Key-Slot (<code>shared=true</code>) Nutzungsdesigns in anderen <code>CryptoKeySlotUserDesign</code>-Instanzen zu.\n</li></ul>\n</li><li>Ein nicht geteilter Key-Slot (<code>shared=false</code>) besitzt ausschließlich eine <code>Owner</code>-Relation und keine <code>User</code>-Relationen. Ein geteilter Key-Slot (<code>shared=true</code>) besitzt genau einen <code>Owner</code> und mehrere <code>User</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Entwurfsmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Beziehungen definieren Rollenallokationen (<code>Owner</code>, <code>User</code>) zur Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Beispiel zur Strukturierung von Manifest-Modellen im Crypto-Stack:</p>\n<ul class=\"fig-list\"><li>Verdeutlicht die Trennung zwischen Key-Slot-Definition (<code>CryptoKeySlotDesign</code>) und Key-Slot-Verwendung (<code>CryptoKeySlotUserDesign</code> / <code>CryptoKeySlotUsageDesign</code>).\n</li><li>Bei <code>shared=false</code> darf ausschließlich eine Zuweisung über die Rolle <code>Owner</code> erfolgen; <code>User</code>-Zuordnungen sind unzulässig.\n</li><li>Bei <code>shared=true</code> können neben dem verpflichtenden <code>Owner</code> mehrere Clients als <code>User</code> auf denselben Key-Slot zugreifen.\n</li><li>Eigenschaften wie <code>cryptoAgorithmID</code>, <code>CryptoObjectType</code> und <code>cryptoKeySlotAllowedUsage</code> konfigurieren die kryptografischen Randbedingungen des Slots auf Architekturebene.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ec3fad993ffa1f92", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturdiagramm / konzeptionelles Entwurfsmodell zur Veranschaulichung des High-Level-Krypto-Designs als Teil des Systementwurfsmodells in AUTOSAR Adaptive Platform (TPS Manifest Specification).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei Kategorien von Modellelementen und deren Beziehungen dar:</p>\n<ul class=\"fig-list\"><li><strong><code>CryptoKeySlotDesign</code></strong>: Repräsentiert die Design-Ebene eines Key-Slots mit der Eigenschaft <code>shared: true</code>.\n</li><li><strong><code>CryptoKeySlotUserDesign</code></strong>: Repräsentiert die Design-Ebene eines Verwenders von Key-Slots. Es enthält als Aggregation bzw. Unterelement ein oder mehrere <strong><code>CryptoKeySlot-UsageDesign</code></strong> (<code>CryptoKeySlotUsageDesign</code>).\n</li><li><strong>Beziehungen</strong>:\n<ul class=\"fig-list\"><li>Gerichtete Assoziationen mit Rollenbezeichnungen führen von <code>CryptoKeySlotDesign</code> auf die enthaltenen <code>CryptoKeySlot-UsageDesign</code>-Elemente:\n<ul class=\"fig-list\"><li><code>Owner</code>: Weist die Eigentümerschaft des Key-Slots einem Nutzungsdesign innerhalb eines <code>CryptoKeySlotUserDesign</code> zu.\n</li><li><code>User</code>: Weist Nutzungsrechte an einem Key-Slot Nutzungsdesigns in separaten <code>CryptoKeySlotUserDesign</code>-Instanzen zu.\n</li></ul>\n</li><li>Dargestellt sind zwei Instanzen von <code>CryptoKeySlotDesign</code> (beide mit <code>shared: true</code> annotiert), wovon eine mit einem <code>Owner</code> und zwei <code>User</code>-Instanzen verknüpft ist, während die andere ausschließlich einen <code>Owner</code> referenziert.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Entwurfsmodell ohne dynamische Ablauf- oder Sequenzdarstellung. Die Beziehungen definieren Rollenallokationen (<code>Owner</code>, <code>User</code>) zur Entwurfszeit.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Beispiel zur Strukturierung von Manifest-Modellen im Crypto-Stack:</p>\n<ul class=\"fig-list\"><li>Verdeutlicht die Trennung zwischen Key-Slot-Definition (<code>CryptoKeySlotDesign</code>) und Key-Slot-Verwendung (<code>CryptoKeySlotUserDesign</code> / <code>CryptoKeySlot-UsageDesign</code>).\n</li><li>Ein nicht geteilter Key-Slot besitzt laut Begleittext ausschließlich einen Eigentümer (<code>Owner</code>), aber keine externen Nutzer (<code>User</code>), wenngleich im Diagramm beide Slots als <code>shared: true</code> deklariert sind.\n</li><li>Ein geteilter Key-Slot bindet neben dem <code>Owner</code> zusätzliche Clients über <code>User</code>-Relationen an.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-e4a0ef5b7f43a824", "to": "FIG-ec3fad993ffa1f92", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>CryptoKeySlotDesign</code> (rechts): Eigenschaft <code>shared</code> geändert von <code>=false</code> zu <code>: true</code>.\n</li><li><code>CryptoKeySlotDesign</code> (beide Instanzen): Attribute <code>cryptoAgorithmID</code>, <code>CryptoObjectType</code> und <code>cryptoKeySlotAllowedUsage</code> entfernt.\n</li><li><code>CryptoKeySlotDesign</code> (Attribute): Syntax der Zuweisung geändert von <code>+ shared=...</code> zu <code>shared: ...</code>.\n</li><li><code>CryptoKeySlotUsageDesign</code>: Typbezeichnung in allen vier Vorkommen mit Trennstrich umbrochen (<code>CryptoKeySlot-</code> / <code>UsageDesign</code>).\n</li><li>Erläuterungskästen: Schlagschatten entfernt und Textumbruch im Hinweiskasten rechts unten angepasst.\n</li></ul>"}]};
